    'pricing.note': { en: "* Indicative only. Final pricing depends on size, plating, attachments and artwork complexity. Mould fees are waived on larger runs. Shipping quoted separately.", zh: "* 仅供参考。最终价格取决于尺寸、镀色、配件与图案复杂度。大批量免模具费。运费另计。", es: "* Solo indicativo. El precio final depende de tamaño, chapado, accesorios y complejidad del arte. Se omiten moldes en tiradas grandes. Envío se cotiza aparte.", fr: "* Indicatif uniquement. Le prix final dépend taille, placage, fixations et complexité de l'œuvre. Frais de moule supprimés sur grandes séries. Livraison devisée séparément.", de: "* Nur Richtwert. Der Endpreis hängt von Größe, Vergoldung, Befestigung und Motivkomplexität ab. Werkzeugkosten ab Großserien entfallen. Versand separat kalkuliert." },
    'pricing.card1.h': { en: "Low MOQ", zh: "低起订量", es: "Pedido mínimo bajo", fr: "Petit minimum", de: "Niedrige Mindestmenge" },
    'pricing.card1.p': { en: "Order as few as 100 pieces — ideal for testing a design or a limited drop.", zh: "最少 100 个即可——适合测试设计或限量发售。", es: "Pide desde solo 100 piezas, ideal para probar un diseño o un lanzamiento limitado.", fr: "Commandez dès 100 pièces — idéal pour tester un design ou un drop limité.", de: "Schon ab 100 Stück bestellen — ideal zum Testen eines Designs oder eines limitierten Drops." },
    'pricing.card2.h': { en: "Bulk discounts", zh: "量大优惠", es: "Descuentos por volumen", fr: "Remises de gros", de: "Mengenrabatte" },
    'pricing.card2.p': { en: "The more you order, the lower the unit price, and mould fees drop away.", zh: "订得越多，单价越低，模具费也随之免除。", es: "Cuanto más pides, más baja la unidad, y los moldes se eliminan.", fr: "Plus vous commandez, plus le prix unitaire baisse, et les frais de moule disparaissent.", de: "Je mehr Sie bestellen, desto niedriger der Stückpreis, und Werkzeugkosten entfallen." },
    'pricing.card3.h': { en: "No hidden fees", zh: "无隐藏费用", es: "Sin cargos ocultos", fr: "Sans frais cachés", de: "Keine versteckten Gebühren" },
    'pricing.card3.p': { en: "Artwork, proofing and revisions are included. You see the full cost up front.", zh: "设计、打样与修改均包含在内。您事先即可看到全部费用。", es: "Arte, muestras y revisiones incluidos. Ves el costo total por adelantado.", fr: "Artwork, épreuves et révisions inclus. Vous voyez le coût total d'avance.", de: "Gestaltung, Proofing und Korrekturen inklusive. Sie sehen die Gesamtkosten im Voraus." },
    'pricing.cta': { en: "Request a tailored quote →", zh: "获取专属报价 →", es: "Solicitar cotización a medida →", fr: "Demander un devis sur mesure →", de: "Individuelles Angebot anfordern →" },
    'gallery.eyebrow.hero': { en: "Portfolio", zh: "作品集", es: "Portafolio", fr: "Portfolio", de: "Portfolio" },
    'gallery.hero.title': { en: "Our <span class='hl'>work</span>", zh: "我们的<span class='hl'>作品</span>", es: "Nuestro <span class='hl'>trabajo</span>", fr: "Nos <span class='hl'>réalisations</span>", de: "Unsere <span class='hl'>Arbeiten</span>" },
    'gallery.hero.sub': { en: "A glimpse of enamel pins, badges and brooches we've produced for brands, events and creators. Yours could be next.", zh: "我们为品牌、活动与创作者制作的珐琅徽章、胸针与奖牌一瞥。下一个也许就是您的。", es: "Un vistazo a los pines, insignias y broches de esmalte que hemos hecho para marcas, eventos y creadores. El tuyo podría ser el próximo.", fr: "Un aperçu des épingles, badges et broches en émail que nous avons produits pour des marques, événements et créateurs. Le vôtre pourrait être le prochain.", de: "Ein Blick auf die Emailleschilder, Abzeichen und Broschen, die wir für Marken, Events und Creator gefertigt haben. Ihres könnte das nächste sein." },
    'gallery.hero.cta': { en: "Start yours →", zh: "开始您的定制 →", es: "Inicia el tuyo →", fr: "Lancez le vôtre →", de: "Starten Sie Ihren →" },
    'gallery.filter.all': { en: "All", zh: "全部", es: "Todos", fr: "Tout", de: "Alle" },
    'gallery.filter.brand': { en: "Brand & Logo", zh: "品牌与 Logo", es: "Marca y Logo", fr: "Marque & Logo", de: "Marke & Logo" },
    'gallery.filter.event': { en: "Events", zh: "活动", es: "Eventos", fr: "Événements", de: "Events" },
